<h1 class="h3 mb-4"><?= $id?'Modifica utente':'Nuovo utente' ?></h1><form method="post" action="/app/utenti<?= $id?'/'.(int)$id:'' ?>" class="card border-0 shadow-sm"><div class="card-body"><div class="row g-3"><?php foreach(['nome'=>'Nome','cognome'=>'Cognome','email'=>'Email','telefono'=>'Telefono'] as $k=>$label): ?><div class="col-md-6"><label class="form-label"><?= e($label) ?></label><input class="form-control" name="<?= e($k) ?>" value="<?= e($utente[$k]??'') ?>" required></div><?php endforeach ?><div class="col-md-6"><label class="form-label">Ruolo</label><select class="form-select" name="ruolo_id" required><?php foreach($ruoli as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (string)$r['id']===(string)($utente['ruolo_id']??'')?'selected':'' ?>><?= e($r['nome']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Password <?= $id?'(vuota per non modificarla)':'' ?></label><input class="form-control" type="password" name="password" <?= $id?'':'required' ?> minlength="12"></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="attivo" value="1" <?= ($utente['attivo']??1)?'checked':'' ?>><label class="form-check-label">Account attivo</label></div></div><?= $csrf->field() ?><button class="btn btn-primary mt-4">Salva</button></div></form>
